     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	
     6	/** Valores em dinheiro: sempre 2 casas, arredondamento "meio para o par". */
     7	public final class Money {
     8	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
     9	
    10	    private Money() {}
    11	
    12	    public static BigDecimal round(BigDecimal v) {
    13	        return v.setScale(2, RoundingMode.HALF_EVEN);
    14	    }
    15	
    16	    public static BigDecimal of(String v) {
    17	        return round(new BigDecimal(v));
    18	    }
    19	
    20	    /** "1.234,56" (pt-BR) */
    21	    public static String br(BigDecimal v) {
    22	        return format(v, '.', ',');
    23	    }
    24	
    25	    /** "1,234.56" (en) */
    26	    public static String en(BigDecimal v) {
    27	        return format(v, ',', '.');
    28	    }
    29	
    30	    /** "1234.56" (CSV) */
    31	    public static String plain(BigDecimal v) {
    32	        return round(v).toPlainString();
    33	    }
    34	
    35	    private static String format(BigDecimal v, char group, char decimal) {
    36	        String plain = round(v).abs().toPlainString();
    37	        int dot = plain.indexOf('.');
    38	        String ints = plain.substring(0, dot);
    39	        String frac = plain.substring(dot + 1);
    40	        StringBuilder sb = new StringBuilder();
    41	        for (int i = 0; i < ints.length(); i++) {
    42	            if (i > 0 && (ints.length() - i) % 3 == 0) sb.append(group);
    43	            sb.append(ints.charAt(i));
    44	        }
    45	        return (v.signum() < 0 ? "-" : "") + sb + decimal + frac;
    46	    }
    47	}
