     1	package pousada;
     2	
     3	import pousada.Domain.RatePlan;
     4	
     5	import java.math.BigDecimal;
     6	import java.time.LocalDate;
     7	
     8	public final class Pricing {
     9	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    11	
    12	    private Pricing() {}
    13	
    14	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    15	
    16	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
    17	    public static boolean isHighSeason(LocalDate night) {
    18	        int m = night.getMonthValue();
    19	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
    20	    }
    21	
    22	    public static BigDecimal nightPrice(BigDecimal rate, LocalDate night) {
    23	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON)) : Money.round(rate);
    24	    }
    25	
    26	    public static Quote quote(BigDecimal rate, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    27	        BigDecimal subtotal = Money.ZERO;
    28	        int nights = 0;
    29	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    30	            subtotal = Money.round(subtotal.add(nightPrice(rate, d)));
    31	            nights++;
    32	        }
    33	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    34	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    35	                : Money.ZERO;
    36	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    37	    }
    38	}

