    30	    DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    31	
    32	    static String digits(String s) {
    33	        return s.replaceAll("\\D", "");
    34	    }
    35	
    36	    static String formatCpf(String s) {
    37	        String d = digits(s);
    38	        return d.length() == 11
    39	                ? d.substring(0, 3) + "." + d.substring(3, 6) + "." + d.substring(6, 9) + "-" + d.substring(9)
    40	                : s;
    41	    }
    42	
    43	    static String formatCnpj(String s) {
    44	        String d = digits(s);
    45	        return d.length() == 14
    46	                ? d.substring(0, 2) + "." + d.substring(2, 5) + "." + d.substring(5, 8) + "/"
    47	                        + d.substring(8, 12) + "-" + d.substring(12)
    48	                : s;
    49	    }
    50	
    51	    /** Linhas comuns aos documentos em português. */
    52	    private static String ptBody(Receipt r) {
    53	        StringBuilder sb = new StringBuilder();
    54	        sb.append("Quarto: ").append(r.roomNumber()).append(" (").append(r.roomType()).append(")\n");
    55	        sb.append("Entrada: ").append(BR_DATE.format(r.checkIn()))
    56	          .append(" | Saída: ").append(BR_DATE.format(r.checkOut()))
    57	          .append(" | ").append(r.nights()).append(r.nights() == 1 ? " diária" : " diárias").append('\n');
    58	        sb.append("Diárias: R$ ").append(Money.br(r.subtotal())).append('\n');
    59	        if (r.discount().signum() > 0) {
    60	            sb.append("Desconto: R$ ").append(Money.br(r.discount())).append('\n');
    61	        }
    62	        sb.append("Total: R$ ").append(Money.br(r.total()));
    63	        return sb.toString();
    64	    }
    65	
    66	    /** Pessoa física, com CPF. */
    67	    record Individual(String cpf) implements Identification {
    68	        public String title() { return "Comprovante de reserva"; }
    69	
    70	        public String render(Receipt r) {
    71	            return "Comprovante de reserva nº " + r.reservationId() + "\n"
    72	                    + "Hóspede: " + r.guestName() + " (CPF " + formatCpf(cpf) + ")\n"
    73	                    + ptBody(r);
    74	        }
    75	    }
    76	
    77	    /** Empresa, com CNPJ; recebe fatura com ISS retido. */
    78	    record Company(String cnpj, String companyName) implements Identification {
    79	        private static final BigDecimal ISS = new BigDecimal("0.05");
    80	
    81	        public String title() { return "Fatura de hospedagem"; }
    82	
    83	        public String render(Receipt r) {
    84	            return "Fatura de hospedagem nº " + r.reservationId() + "\n"
