    86	                    + "Hóspede: " + r.guestName() + "\n"
    87	                    + ptBody(r) + "\n"
    88	                    + "ISS retido (5%): R$ " + Money.br(Money.round(r.total().multiply(ISS)));
    89	        }
    90	    }
    91	
    92	    /** Estrangeiro, com passaporte; recebe o booking receipt em inglês. */
    93	    record Foreigner(String passport, String country) implements Identification {
    94	        private static final DateTimeFormatter ISO = DateTimeFormatter.ISO_LOCAL_DATE;
    95	
    96	        public String title() { return "Booking receipt"; }
    97	
    98	        public String render(Receipt r) {
    99	            StringBuilder sb = new StringBuilder();
   100	            sb.append("Booking receipt no. ").append(r.reservationId()).append('\n');
   101	            sb.append("Guest: ").append(r.guestName()).append(" (passport ").append(passport)
   102	              .append(", ").append(country).append(")\n");
   103	            sb.append("Room: ").append(r.roomNumber()).append(" (").append(r.roomType()).append(")\n");
   104	            sb.append("Check-in: ").append(ISO.format(r.checkIn()))
   105	              .append(" | Check-out: ").append(ISO.format(r.checkOut()))
   106	              .append(" | ").append(r.nights()).append(r.nights() == 1 ? " night" : " nights").append('\n');
   107	            sb.append("Nights: BRL ").append(Money.en(r.subtotal())).append('\n');
   108	            if (r.discount().signum() > 0) {
   109	                sb.append("Discount: BRL ").append(Money.en(r.discount())).append('\n');
   110	            }
   111	            sb.append("Total: BRL ").append(Money.en(r.total()));
   112	            return sb.toString();
   113	        }
   114	    }
   115	
   116	    /** Monta a identificação a partir dos cinco campos (os não usados são null). */
   117	    static Identification from(String cpf, String cnpj, String companyName, String passport, String country) {
   118	        if (cpf != null) return new Individual(cpf);
   119	        if (cnpj != null) return new Company(cnpj, companyName);
   120	        return new Foreigner(passport, country);
   121	    }
   122	}
