    27	    /** Espera o banco ficar disponível e cria o que faltar (banco começa vazio). */
    28	    public void init() {
    29	        long deadline = System.currentTimeMillis() + 60_000;
    30	        while (true) {
    31	            try {
    32	                tx(c -> {
    33	                    try (Statement st = c.createStatement()) {
    34	                        // serializa a criação se vários processos sobem juntos
    35	                        st.execute("SELECT pg_advisory_xact_lock(727274)");
    36	                        st.execute(SCHEMA);
    37	                        st.execute("""
    38	                                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    39	                                  (101, 'STANDARD', 2, 249.90),
