    44	                                ON CONFLICT (number) DO NOTHING""");
    45	                    }
    46	                    return null;
    47	                });
    48	                return;
    49	            } catch (SQLException e) {
    50	                if (System.currentTimeMillis() > deadline) {
    51	                    throw new IllegalStateException("Banco de dados indisponível: " + e.getMessage(), e);
    52	                }
    53	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
    54	            }
    55	        }
    56	    }
