    13	    public interface TxWork<T> {
    14	        T run(Connection c) throws SQLException;
    15	    }
    16	
    17	    public Db(String url, String user, String password) {
    18	        HikariConfig cfg = new HikariConfig();
    19	        cfg.setJdbcUrl(url);
    20	        cfg.setUsername(user);
    21	        cfg.setPassword(password);
    22	        cfg.setMaximumPoolSize(10);
    23	        cfg.setInitializationFailTimeout(-1); // a conexão é validada em init(), com tentativas
    24	        this.ds = new HikariDataSource(cfg);
    25	    }
    26	
    27	    /** Espera o banco ficar disponível e cria o que faltar (banco começa vazio). */
    28	    public void init() {
    29	        long deadline = System.currentTimeMillis() + 60_000;
    30	        while (true) {
    31	            try {
    32	                tx(c -> {
    33	                    try (Statement st = c.createStatement()) {
    34	                        // serializa a criação se vários processos sobem juntos
    35	                        st.execute("SELECT pg_advisory_xact_lock(727274)");
    36	                        st.execute(SCHEMA);
    37	                        st.execute("""
    38	                                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    39	                                  (101, 'STANDARD', 2, 249.90),
    40	                                  (102, 'STANDARD', 2, 249.90),
    41	                                  (201, 'DELUXE',   3, 389.90),
    42	                                  (202, 'DELUXE',   3, 389.90),
    43	                                  (301, 'SUITE',    4, 579.90)
    44	                                ON CONFLICT (number) DO NOTHING""");
    45	                    }
    46	                    return null;
    47	                });
    48	                return;
    49	            } catch (SQLException e) {
    50	                if (System.currentTimeMillis() > deadline) {
    51	                    throw new IllegalStateException("Banco de dados indisponível: " + e.getMessage(), e);
    52	                }
    53	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
    54	            }
    55	        }
    56	    }
    57	
    58	    public <T> T tx(TxWork<T> work) throws SQLException {
    59	        try (Connection c = ds.getConnection()) {
    60	            c.setAutoCommit(false);
    61	            try {
    62	                T result = work.run(c);
    63	                c.commit();
    64	                return result;
    65	            } catch (SQLException | RuntimeException e) {
    66	                c.rollback();
    67	                throw e;
    68	            }
    69	        }
    70	    }
